userscript.function:

        	var itemId = '';
            switch (obj.APP_TYPE) {
                case 'J01':	//법인인감 날인요청
                    callFunction('SLM_211', 'doQuery', [obj.SUX_WKEY1, 'N', 'APP']);
                    itemId = 'MARK_CORP';
                    break;
                case 'J02':	// 사용인감 날인요청
                    callFunction('SLM_221', 'doQuery', [obj.SUX_WKEY1, 'N', 'APP']);
                    itemId = 'MARK_USE';
                    break;
                case 'J03': // 사용인감 반출요청
        			callFunction('SLM_501', 'doQuery', [obj.SUX_WKEY1, 'N', 'APP']);
	            	itemId = 'MARK_EXT';
	            	break;
                case 'E01': // 공동인증서 반출요청
        			callFunction('SPC_001', 'doQuery', [obj.SUX_WKEY1, 'N', 'APP']);
	            	itemId = 'MARK_CERT_EXT';
	            	break;
	            case 'J04': // 법인인감 등록신청
	            	callFunction('SLM_123', 'doLoad', [obj.SUX_WKEY2, obj.SUX_WKEY3, 'APP']);
	            	itemId = 'MANAGE_NEW';
	            	break;
	            case 'J05':	// 사용인감 등록신청
	            	callFunction('SLM_123', 'doLoad', [obj.SUX_WKEY2, obj.SUX_WKEY3, 'APP']);
	            	itemId = 'MANAGE_NEW';
	            	break;
	            case 'J06':	// 인감 변경요청
	            	callFunction('SLM_133', 'doLoad', [obj.SUX_WKEY2, obj.SUX_WKEY3]);
	            	itemId = 'MANAGE_UP';
	            	break;
	            case 'J07':	// 인감 반납요청
	            	callFunction('SLM_143', 'doLoad', [obj.SUX_WKEY2, obj.SUX_WKEY3]);
	            	itemId = 'MANAGE_LOSS';
	            	break;
	            case 'J08':	// 인감 분실신고
	            	callFunction('SLM_153', 'doLoad', [obj.SUX_WKEY2, obj.SUX_WKEY3]);
	            	itemId = 'MANAGE_RET';
	            	break;
            	case 'J09':	// 증명서발급신청
            		callFunction('SLM_251', 'doQuery', [obj.SUX_WKEY1, 'N', 'APP']);
            		itemId = 'MARK_CERT';
	            	break;
                case 'C01' : // 전자계약
                    callFunction('CT_502_L', 'doOpenDocument', [{
                        module: {
                            WORK_TYPE: 'C',                          // T: template, C:contract
                            CONT_TYPE: 'B',                          // B: Business, E: Employee
                            CONT_MODULE: 'APPROVAL'
                        }, 
                        document: {
                            CONT_TYPE : 'B', //B: Business, E: Employee
                            CONT_NO : obj.SUX_WKEY3,
                            CONT_GL_SEQ : obj.SUX_WKEY4
                        },
                        editor: {
                            header:[]
                        }
                    }]);

                    itemId = 'CONTRACT';
                    break;
                default:
                    break;
            }
            carouselObj.cells(itemId).setActive();
